    // ======================================================================
    void Start()
    {
        player = builder.PlayerCtrl;
        cam = player.cam;
        camComp = cam.GetComponent<Camera>();
        PriyaRoomPlayer.Locked = true;
        startPos = player.transform.position;
        SetupAudio();
        SetupPolish();
        SetupDust();

        kamala = CharacterNPC.Create(builder.Root, KamalaIdle, NpcStyle.Kamala(), "Kamala_Kapoor");
        kamala.lookTarget = cam;
        kamala.transform.localRotation = Quaternion.identity;

        titleAmbience = StartCoroutine(RampAmbience(0f, 0.35f, 3f)); // quiet bed under the title screen
        menu = new GameMenu();
        menu.OnPlay = OnMenuPlay;
    }

    void Update()
    {
        var kb = Keyboard.current;
        var ms = Mouse.current;

        // ---- title screen
        if (phase == Phase.Title)
        {
            Cursor.lockState = CursorLockMode.None; Cursor.visible = true;
            menu.Update();
            return;
        }

        // ---- pause
        if (kb != null && kb.escapeKey.wasPressedThisFrame && phase != Phase.Ending) SetPaused(!paused);
        if (paused) return;

        if (kb != null && kb.spaceKey.wasPressedThisFrame) skipLine = true;
        // Enter = skip the whole conversation / cutscene (choices still wait for you)
        if (kb != null && kb.enterKey.wasPressedThisFrame && dlgOptions == null
            && (phase == Phase.Intro || phase == Phase.Dialogue || phase == Phase.Ending))
        { skipAll = true; skipLine = true; }
        if (phase == Phase.Explore) skipAll = false;
        if (openingVoices && kb != null && (kb.enterKey.wasPressedThisFrame || kb.numpadEnterKey.wasPressedThisFrame)) StopOpening();
        if (kb != null && kb.jKey.wasPressedThisFrame && phase == Phase.Explore) journalOpen = !journalOpen;

        fade = Mathf.MoveTowards(fade, fadeTarget, fadeSpeed * Time.deltaTime);

        if (bellEnabled && phase == Phase.Explore && !voice.isPlaying && Time.time > nextBell)
        {
            bell.PlayOneShot(bellClip, 0.16f);
            nextBell = Time.time + UnityEngine.Random.Range(14f, 24f);
        }

        if (phase == Phase.Ending)
        {
            if (showEndPrompt && kb != null && kb.rKey.wasPressedThisFrame) builder.Build();
            return;
        }

        UpdateInteraction();
        UpdateObjective();

        if (phase == Phase.Explore)
        {
            bool quiet = Time.time > thoughtUntil + 0.5f && PlayerInsideRoom();
            if (quiet && !dlgDone && foundCount >= 3) StartCoroutine(KamalaDialogue());
            else if (quiet && dlgDone && foundCount >= TotalClues && !allCluesTriggered) StartCoroutine(AllCluesFound());
        }
    }

    void SetPaused(bool p)
    {
        paused = p;
        GameState.SetPaused(p);
    }

    void OnDestroy()
    {
        Time.timeScale = 1f;
        AudioListener.pause = false;
    }

    void UpdateObjective()
    {
        switch (phase)
        {
            case Phase.Explore:
                if (!PlayerInsideRoom() && foundCount == 0)
                    objective = "Walk through the door into Priya's room";
                else if (foundCount < TotalClues)
                    objective = "Find all " + TotalClues + " clues in the room   (" + foundCount + " of " + TotalClues + " found)";
                else if (!dlgDone)
                    objective = "Talk to Mrs. Kapoor";
                else
                    objective = "All clues found.";
                break;
            case Phase.Dialogue: objective = ""; break;
        }
    }

    // ================================================================ HELPERS
    bool PlayerInsideRoom() { return builder.transform.InverseTransformPoint(player.transform.position).z > -2.0f; }

    bool PlayerClearOfDoor()
    {
        var p = builder.transform.InverseTransformPoint(player.transform.position);
        return p.z > -1.6f || Mathf.Abs(p.x + 2f) > 1.6f;
    }

    void ShowThought(string head, string body, float dur)
    {
        thoughtHead = head; thoughtBody = body; thoughtUntil = Time.time + dur;
    }

    void ShowTitle(string a, string b, float dur)
    {
        titleA = a; titleB = b; titleStart = Time.time; titleEnd = Time.time + dur;
    }

    void Toast(string t, float dur = 3.5f) { toast = t; toastUntil = Time.time + dur; }

    IEnumerator W(float seconds)
    {
        float t = 0;
        while (t < seconds && !skipAll) { t += Time.deltaTime; yield return null; }
    }

    static AudioClip VO(string file) { return Resources.Load<AudioClip>("VO/" + file); }

    /// <summary>Arjun asks Mrs. Kapoor the chosen question aloud, in his recorded voice, before she answers.
    /// E or Space skips it; with no recording her answer follows at once, as it did before.</summary>
    IEnumerator ArjunAsks(string text, string file)
    {
        var clip = VO(file);
        if (clip == null || skipAll) yield break;
        dlgSpeaker = "ARJUN"; dlgText = text;
        voice.Stop(); voice.clip = clip; voice.Play();
        yield return null;                                  // the press that chose the question does not skip it
        float t = 0f, dur = clip.length + 0.16f;
        while (t < dur)
        {
            if (GameState.Paused) { yield return null; continue; }
            var kb = Keyboard.current;
            if (skipAll || GameInput.InteractPressed || (kb != null && kb.spaceKey.wasPressedThisFrame)) { voice.Stop(); break; }
            t += Time.deltaTime;
            yield return null;
        }
    }

    /// <summary>Plays a voice line with a subtitle. Space skips the line.</summary>
    IEnumerator Say(string file, string speaker, string text, bool useKamala = false)
    {
        if (skipAll) { sub = null; yield break; }
        var clip = VO(file);
        float dur = clip != null ? clip.length + 0.16f : Mathf.Max(2.5f, text.Length * 0.06f);
        sub = speaker + ":  " + text;
        subUntil = Time.time + dur + 0.2f;
        subSkippable = true;
        if (clip != null)
        {
            if (useKamala && kamala != null) kamala.Say(clip);
            else { voice.Stop(); voice.clip = clip; voice.Play(); }
        }
        skipLine = false;
        float t = 0;
        while (t < dur && !skipLine && !skipAll) { t += Time.deltaTime; yield return null; }
        if (skipLine || skipAll)
        {
            voice.Stop();
            if (kamala != null) kamala.Silence();
            skipLine = false;
        }
        sub = null; subSkippable = false;
    }

    IEnumerator Turn(Vector3 worldTarget, float dur)
    {
        Vector3 d = worldTarget - cam.position;
        float yaw = Mathf.Atan2(d.x, d.z) * Mathf.Rad2Deg;
        float hd = new Vector2(d.x, d.z).magnitude;
        float pitch = -Mathf.Atan2(d.y, hd) * Mathf.Rad2Deg;
        float y0 = player.Yaw, p0 = player.Pitch, t = 0;
        while (t < dur)
        {
            t += Time.deltaTime;
            float k = Mathf.SmoothStep(0, 1, t / dur);
            player.SetLook(Mathf.LerpAngle(y0, yaw, k), Mathf.Lerp(p0, pitch, k));
            yield return null;
        }
    }

    // ================================================================== INTRO
    IEnumerator Intro()
    {
        phase = Phase.Intro;
        fade = 1f; fadeTarget = 1f;
        objective = "";
        Cursor.lockState = CursorLockMode.Locked; Cursor.visible = false;
        // he already faces Mrs. Kapoor when the landing fades in (it used to turn him to her, then to the door)
        if (kamala != null)
        {
            Vector3 d = kamala.transform.position + Vector3.up * 1.5f - cam.position;
            player.SetLook(Mathf.Atan2(d.x, d.z) * Mathf.Rad2Deg, -Mathf.Atan2(d.y, new Vector2(d.x, d.z).magnitude) * Mathf.Rad2Deg);
        }
        else player.SetLook(0f, 0f);

        yield return W(0.5f);
        ShowTitle("ACT I  -  THE EMPTY ROOM", "Chandnipur, Old Quarter   |   Tuesday evening   |   6:00 PM", 4.4f);
        StartCoroutine(RampAmbience(ambience.volume, 0.9f, 4f));
        bellEnabled = true; nextBell = Time.time + 9f;
        fadeSpeed = 1.15f; fadeTarget = 0f;
        yield return W(0.7f);

        // Control comes back as the landing fades in. The title, Arjun's narration and Mrs. Kapoor's welcome play over
        // free movement, and stop cleanly if he walks into the room, examines a clue or presses Enter.
        skipAll = false;
        PriyaRoomPlayer.Locked = false;
        phase = Phase.Explore;
        lastProgressTime = Time.time;
        startPos = player.transform.position;
        StartCoroutine(OpeningVoices());
    }

