    IEnumerator OpeningVoices()
    {
        openingVoices = true;
        foreach (var l in Opening)
        {
            bool hers = l[3] == "her";
            // she welcomes him on the landing: once he is in Priya's room her lines would talk to an empty hallway
            if (!openingVoices || (hers && (kamala == null || PlayerInsideRoom()))) break;
            var clip = VO(l[0]);
            float dur = clip != null ? clip.length + 0.16f : Mathf.Max(2.5f, l[2].Length * 0.06f);
            sub = l[1] + ":  " + l[2]; subUntil = Time.time + dur + 0.2f; subSkippable = true;
            openingClip = clip;
            if (clip != null)
            {
                if (hers) kamala.Say(clip);
                else { voice.Stop(); voice.clip = clip; voice.Play(); }
            }
            skipLine = false;
            float t = 0f;
            while (t < dur && openingVoices && !skipLine) { t += Time.deltaTime; yield return null; }
            if (skipLine && openingVoices)
            {
                if (hers) { if (kamala != null) kamala.Silence(); }
                else if (voice.clip == clip) voice.Stop();
                skipLine = false;
            }
        }
        if (openingVoices) { sub = null; subSkippable = false; }
        openingVoices = false; openingClip = null;
    }

    /// <summary>Ends the opening voices at once (a clue, Mrs. Kapoor's questions or Enter take over).</summary>
    void StopOpening()
    {
        if (!openingVoices) return;
        openingVoices = false;
        if (openingClip != null && voice.clip == openingClip) voice.Stop();
        if (kamala != null) kamala.Silence();
        sub = null; subSkippable = false;
        openingClip = null;
    }

    IEnumerator RampAmbience(float from, float to, float dur)
    {
        float t = 0;
        while (t < dur)
        {
            t += Time.deltaTime;
            ambience.volume = Mathf.Lerp(from, to, t / dur);
            yield return null;
        }
        ambience.volume = to;
    }

    // =========================================================== INTERACTION
    bool Aim(Vector3 p, float maxDist, out float angle)
    {
        angle = 999f;
        Vector3 d = p - cam.position;
        float dist = d.magnitude;
        if (dist > maxDist || dist < 0.05f) return false;
        angle = Vector3.Angle(cam.forward, d);
        float lim = Mathf.Clamp(Mathf.Atan2(0.3f, dist) * Mathf.Rad2Deg, 5f, 16f);
        if (angle > lim) return false;
        if (Physics.Raycast(cam.position, d.normalized, Mathf.Max(0f, dist - 0.3f))) return false;
        return true;
    }

    Vector3 Center(ClueTag t)
    {
        if (t.id.StartsWith("Hook")) return t.transform.position + Vector3.up * 0.03f;
        Vector3 c;
        if (!centers.TryGetValue(t, out c))
        {
            Bounds b = new Bounds(t.transform.position, Vector3.zero);
            bool first = true;
            foreach (var r in t.GetComponentsInChildren<Renderer>())
            {
                if (first) { b = r.bounds; first = false; } else b.Encapsulate(r.bounds);
            }
            c = b.center;
            centers[t] = c;
        }
        return c;
    }

    /// <summary>Forgiving "looking roughly at it, and close enough" test (no raycast).</summary>
    bool Near(Vector3 p, float maxDist, float maxAngle, out float angle)
    {
        Vector3 d = p - cam.position;
        angle = Vector3.Angle(cam.forward, d);
        return d.magnitude <= maxDist && angle <= maxAngle;
    }

    /// <summary>Gold on-screen marker for the current goal (door, then note).</summary>
    void DrawGuide(float s, float W, float H)
    {
        Vector3 target;
        string label;
        if (phase == Phase.DoorReady) { target = builder.transform.TransformPoint(new Vector3(-2f, 2.2f, -2.5f)); label = "Door"; }
        else if (phase == Phase.NoteReady && builder.HookNote != null) { target = builder.HookNote.transform.position + Vector3.up * 0.45f; label = "Note"; }
        else return;
        Vector3 sp = camComp.WorldToScreenPoint(target);
        if (sp.z <= 0.1f) { UiKit.Text(new Rect(0, H * 0.3f, W, 28), "Turn around: " + label, new GUIStyle(sPrompt) { fontSize = 18 }); return; }
        float x = Mathf.Clamp(sp.x / s, 40, W - 40), y = Mathf.Clamp((Screen.height - sp.y) / s, 60, H - 80);
        var m = GUI.matrix;
        GUIUtility.RotateAroundPivot(45f, new Vector2(x, y));
        var old = GUI.color; GUI.color = new Color(1f, 0.8f, 0.2f, 0.5f + 0.5f * Mathf.Sin(Time.unscaledTime * 5f));
        GUI.DrawTexture(new Rect(x - 7, y - 7, 14, 14), Texture2D.whiteTexture);
        GUI.color = old;
        GUI.matrix = m;
        UiKit.Text(new Rect(x - 130, y - 38, 260, 24), label + "   " + Vector3.Distance(cam.position, target).ToString("0.0") + " m", new GUIStyle(sSmall) { alignment = TextAnchor.UpperCenter, fontSize = 15 });
    }

    ClueTag lastFocus, shownFocus;
    float lastFocusTime, focusSince;
    Light hoverLight;

    /// <summary>
    /// A small, soft warm light that fades in over the clue the crosshair is on, so a dark object (a maroon suitcase
    /// on a shadowed floor) is readable without making every clue glow all the time.
    /// </summary>
    void UpdateHoverLight(ClueTag t)
    {
        if (hoverLight == null)
        {
            hoverLight = new GameObject("ClueHoverLight").AddComponent<Light>();
            hoverLight.transform.SetParent(builder.Root, false);
            hoverLight.type = LightType.Point; hoverLight.color = new Color(1f, 0.86f, 0.62f);
            hoverLight.range = 1.6f; hoverLight.intensity = 0f; hoverLight.shadows = LightShadows.None;
        }
        var col = t != null ? ClueCollider(t) : null;
        float want = col != null ? 0.55f : 0f;
        if (col != null)
        {
            Bounds b = col.bounds;
            Vector3 toCam = (cam.position - b.center).normalized;
            hoverLight.transform.position = b.center + toCam * Mathf.Max(0.35f, b.extents.magnitude + 0.15f) + Vector3.up * 0.2f;
            hoverLight.range = Mathf.Clamp(b.extents.magnitude * 2.2f + 0.5f, 0.9f, 1.8f);    // reaches the clue, not the walls
        }
        hoverLight.intensity = Mathf.MoveTowards(hoverLight.intensity, want, Time.deltaTime * 6f);
        hoverLight.enabled = hoverLight.intensity > 0.01f;
    }

    static Collider ClueCollider(ClueTag t)
    {
        foreach (var c in t.GetComponents<Collider>()) if (c.isTrigger) return c;
        return null;
    }

    /// <summary>
    /// Which clue is the crosshair on? For every unfound clue we measure how far its centre is from the line of sight and
    /// allow its own size plus about 2.6 degrees of forgiveness (so a small clue is as easy to pick at 3 m as at 1 m).
    /// A clue only counts if it can actually be seen (nothing solid in the way). The best match wins, and the highlight is
    /// held for a split second so it never flickers.
    /// </summary>
    ClueTag LookedAtClue(float maxDist)
    {
        Vector3 o = cam.position, f = cam.forward;
        // 1) exact: the first thing the crosshair ray touches. Each clue has a padded trigger box around it, so the ray
        //    meets that box before the clue's own solid parts. Large or low clues (the suitcase on the floor) are
        //    found wherever on them the crosshair rests, not only near their centre.
        var exact = ClueUnderCrosshair(o, f, maxDist + 0.6f);
        if (exact != null) { lastFocus = exact; lastFocusTime = Time.time; return exact; }

        // 2) forgiving: the nearest clue to the line of sight, so small clues don't need pixel-perfect aim
        ClueTag best = null; float bestScore = float.MaxValue;
        foreach (var t in builder.ClueTags)
        {
            if (t == null || t.found || t.id.StartsWith("Hook") || !t.gameObject.activeInHierarchy) continue;
            var col = ClueCollider(t);
            if (col == null) continue;
            Bounds b = col.bounds;
            Vector3 toC = b.center - o;
            float d = toC.magnitude;
            if (d > maxDist + b.extents.magnitude || d < 0.05f) continue;
            if (Vector3.Dot(toC, f) <= 0.05f) continue;                          // behind us
            float perp = Vector3.Cross(f, toC).magnitude;                         // how far the centre is from the crosshair line
            float allowed = b.extents.magnitude * 0.85f + d * 0.045f + 0.04f;
            if (perp > allowed) continue;
            if (ClueHidden(t, b, o)) continue;
            float score = perp / allowed;
            if (score < bestScore) { bestScore = score; best = t; }
        }
        if (best == null && lastFocus != null && !lastFocus.found && Time.time - lastFocusTime < 0.25f) return lastFocus;   // no flicker at the edges
        if (best != null) { lastFocus = best; lastFocusTime = Time.time; }
        return best;
    }

    readonly RaycastHit[] rayHits = new RaycastHit[24];

    /// <summary>The unfound clue whose hit-box the crosshair ray meets before any solid wall or furniture (null if none).</summary>
    ClueTag ClueUnderCrosshair(Vector3 o, Vector3 f, float range)
    {
        int n = Physics.RaycastNonAlloc(o, f, rayHits, range, ~0, QueryTriggerInteraction.Collide);
        System.Array.Sort(rayHits, 0, n, HitOrder);
        var ray = new Ray(o, f);
        candidates.Clear();
        for (int i = 0; i < n; i++)
        {
            var c = rayHits[i].collider;
            if (c == null || c.GetComponentInParent<PriyaRoomPlayer>() != null) continue;
            var tag = c.GetComponentInParent<ClueTag>();
            bool usable = tag != null && !tag.found && !tag.id.StartsWith("Hook") && tag.gameObject.activeInHierarchy;
            if (c.isTrigger)
            {
                if (usable && ClueCollider(tag) == c && !candidates.Contains(tag)) candidates.Add(tag);
                continue;                                                   // other trigger volumes don't block the view
            }
            if (usable && !candidates.Contains(tag)) candidates.Add(tag);  // standing inside its box: its own solid part
            break;                                                          // a wall, furniture, or a clue already examined
        }
        if (candidates.Count <= 1) return candidates.Count == 1 ? candidates[0] : null;
        // the padded boxes of neighbouring clues overlap (the sticky note sits under the laptop, the photo among the
        // papers): if the crosshair passes through the real outline of several, the smallest - the most specific -
        // wins; if it passes through none, the clue whose outline is closest to the crosshair line wins
        ClueTag best = null; float bestThrough = float.MaxValue, bestNear = float.MaxValue; bool anyThrough = false;
        foreach (var t in candidates)
        {
            ShapeScore(t, ray, out bool through, out float volume, out float near);
            if (through) { anyThrough = true; if (volume < bestThrough) { bestThrough = volume; best = t; } }
            else if (!anyThrough && near < bestNear) { bestNear = near; best = t; }
        }
        return best;
    }

    readonly List<ClueTag> candidates = new List<ClueTag>();

    /// <summary>Does the ray pass through the clue's own outline (and how big is it), or how close does it come?</summary>
    static void ShapeScore(ClueTag t, Ray ray, out bool through, out float volume, out float near)
    {
        through = false; volume = float.MaxValue; near = float.MaxValue;
        foreach (var r in t.GetComponentsInChildren<Renderer>())
        {
            if (!r.enabled) continue;
            var b = r.bounds; b.Expand(0.015f);
            if (b.IntersectRay(ray)) { through = true; volume = Mathf.Min(volume, b.size.x * b.size.y * b.size.z); continue; }
            Vector3 p = ray.GetPoint(Mathf.Max(0f, Vector3.Dot(b.center - ray.origin, ray.direction)));
            near = Mathf.Min(near, Vector3.Distance(p, b.ClosestPoint(p)));
        }
    }

    static readonly System.Comparison<RaycastHit> HitOrderFn = (a, b) => a.distance.CompareTo(b.distance);
    static readonly System.Collections.Generic.IComparer<RaycastHit> HitOrder = System.Collections.Generic.Comparer<RaycastHit>.Create(HitOrderFn);

    /// <summary>True only if every sample point of the clue is behind something solid.</summary>
    bool ClueHidden(ClueTag t, Bounds b, Vector3 o)
    {
        Vector3[] pts = { b.center, b.center + Vector3.up * b.extents.y * 0.8f, b.ClosestPoint(o) };
        foreach (var p in pts)
        {
            Vector3 dir = p - o; float len = dir.magnitude;
            if (len < 0.05f) return false;
            dir /= len;
            bool blocked = false;
            foreach (var h in Physics.RaycastAll(o, dir, len - 0.02f, ~0, QueryTriggerInteraction.Ignore))
            {
                if (h.collider.transform == t.transform || h.collider.transform.IsChildOf(t.transform)) continue;   // the clue's own parts
                if (h.distance < len - 0.12f) { blocked = true; break; }
            }
            if (!blocked) return false;
        }
        return true;
    }

    /// <summary>A gold ring around the clue the crosshair is on, with its name.</summary>
    void DrawFocusRing(float s, float W, float H)
    {
        var t = builder.Focused;
        if (t == null) return;
        var col = ClueCollider(t);
        if (col == null) return;
        Bounds b = col.bounds;
        Vector3 sp = camComp.WorldToScreenPoint(b.center);
        if (sp.z <= 0.1f) return;
        Vector3 edge = camComp.WorldToScreenPoint(b.center + cam.right * Mathf.Max(0.08f, b.extents.magnitude * 0.7f));
        float rad = Mathf.Clamp(Mathf.Abs(edge.x - sp.x) / s + 12f, 34f, 130f);
        // keep the marker on screen even when the clue's centre is near an edge (a suitcase seen from above)
        float x = Mathf.Clamp(sp.x / s, rad + 8f, W - rad - 8f), y = Mathf.Clamp((Screen.height - sp.y) / s, rad + 70f, H - rad - 110f);
        float since = Time.unscaledTime - focusSince;
        float grow = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(since / 0.18f));            // the ring settles in, it does not pop
        float pulse = 0.75f + 0.25f * Mathf.Sin(Time.unscaledTime * 5f);
        float r2 = rad * Mathf.Lerp(1.25f, 1f, grow);
        var ringRect = new Rect(x - r2, y - r2, r2 * 2f, r2 * 2f);
        UiKit.Ring(new Rect(ringRect.x - 2f, ringRect.y - 2f, ringRect.width + 4f, ringRect.height + 4f), new Color(0f, 0f, 0f, 0.55f * grow), 7f);   // dark halo: readable on light or dark
        UiKit.Ring(ringRect, new Color(1f, 0.82f, 0.3f, pulse * grow), 3.5f);
        // the clue's name and what E will do, on a dark tag above the ring
        ClueInfo ci;
        string nm = Info.TryGetValue(t.id, out ci) ? ci.name : "Something here";
        var ns = new GUIStyle(sHead) { alignment = TextAnchor.MiddleCenter, fontSize = 18 };
        var hs = new GUIStyle(sSmall) { alignment = TextAnchor.MiddleCenter, fontSize = 14 };
        float tw = Mathf.Max(ns.CalcSize(new GUIContent(nm)).x, hs.CalcSize(new GUIContent("Press E to examine")).x) + 36f;
        var tag = new Rect(Mathf.Clamp(x - tw / 2f, 8f, W - tw - 8f), y - r2 - 62f, tw, 52f);
        var o = GUI.color; GUI.color = new Color(1, 1, 1, grow);
        UiKit.Card(tag, 0.78f);
        GUI.Label(new Rect(tag.x, tag.y + 5f, tag.width, 24f), nm, ns);
        GUI.Label(new Rect(tag.x, tag.y + 27f, tag.width, 20f), "Press E to examine", hs);
        GUI.color = o;
    }

    void UpdateInteraction()
    {
        prompt = "";
        builder.Focused = null;
        if (PriyaRoomPlayer.Locked || phase == Phase.Intro || phase == Phase.Dialogue || phase == Phase.Ending) { if (hoverLight != null) UpdateHoverLight(null); return; }

        Action act = null;

        // clues: an exact ray from the crosshair against each clue's own hit-box
        ClueTag looked = (phase == Phase.Explore || phase == Phase.Hook || phase == Phase.DoorReady || phase == Phase.NoteReady) ? LookedAtClue(3.4f) : null;
        if (looked != shownFocus) { shownFocus = looked; focusSince = Time.unscaledTime; }
        builder.Focused = looked;
        UpdateHoverLight(looked);
        if (looked != null)
        {
            ClueInfo ci;
            string nm = Info.TryGetValue(looked.id, out ci) ? ci.name : "object";
            var cap = looked;
            prompt = "[E]  Examine " + nm;
            act = () => Examine(cap);
        }

        // the folded note keeps its generous "roughly facing it" test
        if (phase == Phase.NoteReady)
        {
            foreach (var t in builder.ClueTags)
            {
                if (t == null || t.found || !t.id.StartsWith("Hook") || !t.gameObject.activeInHierarchy) continue;
                float a;
                if (Near(Center(t), 4.5f, 42f, out a))
                {
                    var cap = t;
                    prompt = "[E]  Pick up the note";
                    act = () => Examine(cap);
                }
            }
        }

        if (phase == Phase.DoorReady)
        {
            float a;
            var dc = builder.transform.TransformPoint(new Vector3(-2f, 1.1f, -2.5f));
            if (Near(dc, 3.6f, 34f, out a))
            {
                prompt = "[E]  Open the door";
                act = () => StartCoroutine(OpenDoor());
            }
        }

        if (act != null && GameInput.InteractPressed)
        {
            sfx.PlayOneShot(clickClip, 0.6f);
            act();
        }
    }

    void Examine(ClueTag t)
    {
        t.found = true;
        if (t.id.StartsWith("Hook"))
        {
            StartCoroutine(Finale());
            return;
        }
        StopOpening();
        foundCount++;
        SaveSystem.AddClue(t.id);
        lastProgressTime = Time.time;
        ClueInfo ci = Info[t.id];
        var clip = VO("arjun_clue_" + t.id);
        // the card stays up for the voice and for reading it (about 17 characters a second), whichever is longer
        float read = (ci.desc.Length + ci.quote.Length) / 17f + 0.6f;
        float dur = Mathf.Max(clip != null ? clip.length + 0.6f : 5f, read);
        ShowThought("CLUE FOUND:  " + ci.name.ToUpper() + "   (" + foundCount + "/9)",
                    ci.desc + "\n\nARJUN:  \"" + ci.quote + "\"", dur);
        sfx.PlayOneShot(dingClip, 0.5f);
        if (clip != null) { voice.Stop(); voice.clip = clip; voice.Play(); }
        if (foundCount == 9 && moveOnDeclined)
            Toast("You found every clue. Press N to move ahead.", 6f);
    }

    // ============================================================== KAMALA
    IEnumerator KamalaDialogue()
    {
        StopOpening();
        phase = Phase.Dialogue;
        PriyaRoomPlayer.Locked = true;
        objective = "";
        thoughtUntil = 0;
        journalOpen = false;
        sfx.PlayOneShot(clickClip, 0.5f);

        // she walks up to the doorway
        yield return kamala.WalkTo(KamalaDoor, 1.5f);
        AutoFocus.FocusOn = kamala.transform;
        yield return Turn(kamala.transform.position + Vector3.up * 1.5f, 0.9f);

        string[] menu =
        {
            "Did she mention anyone threatening her?",
            "Was she working on anything dangerous?",
            "Did the police search this place?",
            "That's all for now, Mrs. Kapoor.",
        };
        string[] files = { "kamala_a", "kamala_b", "kamala_c" };
        string[] asks = { "q_k_a", "q_k_b", "q_k_c" };          // Arjun's own recordings of the three questions
        string[] replies =
        {
            "Not directly. But two weeks ago, she stopped coming home for dinner. I could hear her on the phone, arguing with someone. She used words like 'forgery' and 'original documents'. I didn't understand, but I understood her voice. She was scared.",
            "Priya's work is always dangerous, Mr. Mehra. She fights for people who have no one else. She told me, 'Maa, if I can prove the land belongs to them, no one can touch them.' She was so hopeful. And then, suddenly, she wasn't.",
            "An inspector came. A woman. She looked around for ten minutes, asked me a few questions, and left. She said Priya probably went to visit a friend. But Priya's phone is here. Her wallet is here. What kind of person leaves without their phone?",
        };
        dlgAsked = new bool[3];

        dlgSpeaker = "KAMALA KAPOOR";
        dlgText = "Have you found anything?";
        var ask = VO("kamala_ask");
        if (ask != null) kamala.Say(ask);
        yield return W(ask != null ? ask.length + 0.3f : 1.5f);

        while (true)
        {
            dlgOptions = menu;
            dlgText = dlgText == null || dlgText.Length == 0 ? "Is there anything else you want to ask me?" : dlgText;
            int choice = -1;
            skipAll = false;
            compass.Open(new[] { "Threats", "Priya’s work", "The police", "Leave" }, menu, asked: dlgAsked);
            yield return null;
            while (choice < 0)
            {
                if (GameState.Paused) { yield return null; continue; }
                choice = compass.Poll();
                yield return null;
            }
            sfx.PlayOneShot(clickClip, 0.5f);
            dlgOptions = null;
            if (choice == 3)
            {
                dlgText = "Please, Mr. Mehra. Find my daughter.";
                var bye = VO("kamala_bye");
                if (bye != null) kamala.Say(bye);
                yield return W(bye != null ? bye.length + 0.6f : 2.5f);
                break;
            }
            dlgAsked[choice] = true;
            yield return ArjunAsks(menu[choice], asks[choice]);
            dlgSpeaker = "KAMALA KAPOOR";
            dlgText = replies[choice];
            var rc = VO(files[choice]);
            if (rc != null) kamala.Say(rc);
            yield return null;
            // wait for the line to finish or for the player to press E / Space
            while (true)
            {
                if (GameState.Paused) { yield return null; continue; }
                var kb = Keyboard.current;
                bool pressed = GameInput.InteractPressed || (kb != null && kb.spaceKey.wasPressedThisFrame);
                if (pressed || skipAll) { kamala.Silence(); break; }
                if (!kamala.IsTalking) { yield return W(0.4f); break; }
                yield return null;
            }
            dlgText = "";
            // Her answer already invites the next question. Keep the witness on camera.
            dlgText = "What else do you want to ask?";
        }

        dlgSpeaker = null; dlgText = null; dlgOptions = null;
        dlgDone = true;
        SaveSystem.Data.dlgDone = true; SaveSystem.Save();
        PriyaRoomPlayer.Locked = false;
        phase = Phase.Explore;
        lastProgressTime = Time.time;
        AutoFocus.FocusOn = null;
        Toast("Mrs. Kapoor heads back down the stairs.", 3.5f);
        thoughtUntil = 0;
        yield return kamala.WalkTo(KamalaExit, 1.6f);
        if (kamala != null) { Destroy(kamala.gameObject); kamala = null; }
    }

