        creakClip = MakeCreak();
        dingClip = MakeDing();
    }

    const int SR = 44100;

    AudioClip MakeAmbience()
    {
        int n = SR * 8, tail = 4000;
        float[] g = new float[n + tail];
        var r = new System.Random(5);
        float lp1 = 0, lp2 = 0, lp3 = 0;
        for (int i = 0; i < g.Length; i++)
        {
            float w = (float)(r.NextDouble() * 2 - 1);
            lp1 += (w - lp1) * 0.02f;
            lp2 += (lp1 - lp2) * 0.06f;
            lp3 += (w - lp3) * 0.25f;
            float t = i / (float)SR;
            float fan = 0.5f + 0.5f * Mathf.Sin(2f * Mathf.PI * 2.5f * t);
            g[i] = lp2 * 5f * (0.7f + 0.3f * fan) + lp3 * 0.05f * fan + 0.012f * Mathf.Sin(2f * Mathf.PI * 50f * t);
        }
        float[] d = new float[n];
        for (int k = 0; k < n; k++)
        {
            if (k < tail) { float a = k / (float)tail; d[k] = g[k] * a + g[n + k] * (1f - a); }
            else d[k] = g[k];
        }
        Normalize(d, 0.45f);
        var c = AudioClip.Create("ambience", n, 1, SR, false);
        c.SetData(d, 0);
        return c;
    }

    AudioClip MakeBell()
    {
        int n = SR * 5;
        float[] d = new float[n];
        float[] f = { 392f, 784f, 1082f, 2117f, 3490f };
        float[] a = { 1f, 0.6f, 0.4f, 0.22f, 0.12f };
        float[] dec = { 0.9f, 1.3f, 1.7f, 2.6f, 3.6f };
        for (int i = 0; i < n; i++)
        {
            float t = i / (float)SR, s = 0;
            for (int p = 0; p < f.Length; p++) s += a[p] * Mathf.Exp(-t * dec[p]) * Mathf.Sin(2f * Mathf.PI * f[p] * t);
            d[i] = s * Mathf.Clamp01(t * 200f);
        }
        Normalize(d, 0.6f);
        var c = AudioClip.Create("bell", n, 1, SR, false);
        c.SetData(d, 0);
        return c;
    }

    AudioClip MakeStep()
    {
        int n = SR / 3;
        float[] d = new float[n];
        var r = new System.Random(9);
        for (int i = 0; i < n; i++)
        {
            float t = i / (float)SR;
            d[i] = Mathf.Sin(2f * Mathf.PI * 75f * t) * Mathf.Exp(-t * 22f) + (float)(r.NextDouble() * 2 - 1) * Mathf.Exp(-t * 45f) * 0.35f;
        }
        Normalize(d, 0.8f);
        var c = AudioClip.Create("step", n, 1, SR, false);
        c.SetData(d, 0);
        return c;
    }

    AudioClip MakeClick()
    {
        int n = SR / 10;
        float[] d = new float[n];
        for (int i = 0; i < n; i++)
        {
            float t = i / (float)SR;
            d[i] = Mathf.Sin(2f * Mathf.PI * 880f * t) * Mathf.Exp(-t * 55f) * 0.5f;
        }
        var c = AudioClip.Create("click", n, 1, SR, false);
        c.SetData(d, 0);
        return c;
    }

    AudioClip MakeDing()
    {
        int n = SR * 6 / 10;
        float[] d = new float[n];
        for (int i = 0; i < n; i++)
        {
            float t = i / (float)SR;
            float a = Mathf.Sin(2f * Mathf.PI * 784f * t) * Mathf.Exp(-t * 7f);
            float b = t > 0.09f ? Mathf.Sin(2f * Mathf.PI * 1175f * (t - 0.09f)) * Mathf.Exp(-(t - 0.09f) * 6f) : 0f;
            d[i] = (a + b) * 0.35f;
        }
        var c = AudioClip.Create("ding", n, 1, SR, false);
        c.SetData(d, 0);
        return c;
    }

    AudioClip MakeCreak()
    {
        int n = SR * 12 / 10;
        float[] d = new float[n];
        float ph = 0;
        for (int i = 0; i < n; i++)
        {
            float t = i / (float)SR;
            float f = 110f + 70f * Mathf.Sin(t * 5f) + 40f * t;
            ph += 2f * Mathf.PI * f / SR;
            float saw = (ph / (2f * Mathf.PI)) % 1f * 2f - 1f;
            d[i] = saw * Mathf.Sin(Mathf.PI * t / 1.2f) * 0.3f;
        }
        var c = AudioClip.Create("creak", n, 1, SR, false);
        c.SetData(d, 0);
        return c;
    }

    static void Normalize(float[] d, float peak)
    {
        float m = 0.0001f;
        for (int i = 0; i < d.Length; i++) m = Mathf.Max(m, Mathf.Abs(d[i]));
        float k = peak / m;
        for (int i = 0; i < d.Length; i++) d[i] *= k;
    }

    // =============================================================== POLISH
    void SetupPolish()
    {
        CinematicLook.Apply(builder.Root, camComp, LookPreset.Apartment);
    }

    void SetupDust()
    {
        var go = new GameObject("DustMotes");
        go.transform.SetParent(builder.Root, false);
        go.transform.localPosition = new Vector3(1.2f, 1.6f, 1.7f);
        var ps = go.AddComponent<ParticleSystem>();
        var main = ps.main;
        main.loop = true; main.prewarm = true;
        main.startLifetime = 9f;
        main.startSpeed = 0.03f;
        main.startSize = 0.012f;
        main.startColor = new Color(1f, 0.85f, 0.55f, 0.7f);
        main.maxParticles = 250;
        main.simulationSpace = ParticleSystemSimulationSpace.World;
        var em = ps.emission; em.rateOverTime = 28f;
        var sh = ps.shape;
        sh.shapeType = ParticleSystemShapeType.Box;
        sh.scale = new Vector3(2.4f, 1.6f, 2.6f);
        var noise = ps.noise; noise.enabled = true; noise.strength = 0.08f; noise.frequency = 0.4f;
        var rend = go.GetComponent<ParticleSystemRenderer>();
        var shader = Shader.Find("Sprites/Default");
        if (shader != null) rend.sharedMaterial = new Material(shader);
    }

    // ==================================================================== UI
    void InitStyles()
    {
        if (sSub != null) return;
        sSub = new GUIStyle(GUI.skin.label) { fontSize = 20, alignment = TextAnchor.MiddleCenter, wordWrap = true };
        sSub.normal.textColor = new Color(1f, 0.95f, 0.85f);
        sTitle = new GUIStyle(GUI.skin.label) { fontSize = 48, alignment = TextAnchor.MiddleCenter, fontStyle = FontStyle.Bold };
        sTitle.normal.textColor = new Color(1f, 0.82f, 0.4f);
        sTitle2 = new GUIStyle(GUI.skin.label) { fontSize = 20, alignment = TextAnchor.MiddleCenter };
        sTitle2.normal.textColor = new Color(0.9f, 0.85f, 0.75f);
        sSmall = new GUIStyle(GUI.skin.label) { fontSize = 17, alignment = TextAnchor.UpperLeft, wordWrap = true };
        sSmall.normal.textColor = new Color(1f, 0.9f, 0.7f);
        sPanel = new GUIStyle(GUI.skin.label) { fontSize = 18, alignment = TextAnchor.UpperLeft, wordWrap = true };
        sPanel.normal.textColor = Color.white;
        sHead = new GUIStyle(sPanel) { fontStyle = FontStyle.Bold, fontSize = 17 };
        sHead.normal.textColor = new Color(1f, 0.82f, 0.4f);
        sPrompt = new GUIStyle(GUI.skin.label) { fontSize = 22, alignment = TextAnchor.MiddleCenter, fontStyle = FontStyle.Bold };
        sPrompt.normal.textColor = new Color(1f, 0.85f, 0.4f);
        UiKit.Skin(sSub, sTitle, sTitle2, sSmall, sPanel, sHead, sPrompt);
        sBtn = UiKit.ButtonStyle();
    }

    static void Panel(Rect r, float alpha) { UiKit.Card(r, alpha); }

    static void Shadowed(Rect r, string t, GUIStyle s) { UiKit.Text(r, t, s); }

    static string Check(bool b) { return b ? "[x] " : "[ ] "; }

    void OnGUI()
    {
        GUI.depth = -10;
        InitStyles();
        float s = Mathf.Max(0.7f, Screen.height / 900f);
        var savedMatrix = GUI.matrix;
        GUI.matrix = Matrix4x4.Scale(new Vector3(s, s, 1));
        float W = Screen.width / s, H = Screen.height / s;

        bool playing = phase == Phase.Explore || phase == Phase.DoorReady || phase == Phase.NoteReady;
        UiKit.Letterbox(W, H, !paused && phase != Phase.Title && (phase == Phase.Intro || !string.IsNullOrEmpty(dlgText)));

        // crosshair
        if (playing && !paused) UiKit.Crosshair(W, H);
        if (playing && !paused && builder.Focused != null) DrawFocusRing(s, W, H);

        // clue markers in detective vision
        if (playing && builder.VisionOn && !paused) DrawMarkers(s, H);
        if (!paused && (phase == Phase.DoorReady || phase == Phase.NoteReady)) DrawGuide(s, W, H);

        if (!string.IsNullOrEmpty(prompt) && !paused)
            UiKit.Prompt(W, H, prompt);

        // objective
        if (!string.IsNullOrEmpty(objective) && !paused)
        {
            var r = new Rect(20, 18, Mathf.Min(560, W * 0.5f), 62);
            Panel(r, 0.5f);
            GUI.Label(new Rect(r.x + 12, r.y + 6, r.width - 24, 20), UiKit.Track("Objective"), sHead);
            GUI.Label(new Rect(r.x + 12, r.y + 27, r.width - 24, 34), objective, sSmall);
        }

        // tutorial checklist
        // it waits while the opening voices' subtitles hold the bottom of the screen (they overlapped it)
        if (phase == Phase.Explore && !paused && !(openingVoices && Time.time < subUntil)) DrawTutorial(W, H);

        // key hints
        if (playing && !paused)
        {
            string hint = "E Examine   |   TAB Detective vision" + (builder.VisionOn ? " [ON]" : "") + "   |   J Journal   |   Esc Pause";
            Shadowed(new Rect(0, H - 30, W - 20, 24), hint, new GUIStyle(sSmall) { alignment = TextAnchor.LowerRight, fontSize = 14 });
        }

        // idle hint if the player seems stuck
        if (phase == Phase.Explore && !paused && !builder.VisionOn && PlayerInsideRoom()
            && Time.time - lastProgressTime > 60f && foundCount < TotalClues)
            Shadowed(new Rect(0, H * 0.7f, W, 30), "Stuck?  Press TAB to reveal clues, or J to see where to look.", sPrompt);

        // toast
        if (Time.time < toastUntil && !string.IsNullOrEmpty(toast) && !paused)
        {
            var r = new Rect(W / 2 - 300, 96, 600, 40);        // below the objective box, not on top of it
            Panel(r, 0.65f);
            GUI.Label(new Rect(r.x, r.y + 6, r.width, 30), toast, new GUIStyle(sPrompt) { fontSize = 18 });
        }

        // clue card
        if (Time.time < thoughtUntil && !string.IsNullOrEmpty(thoughtBody) && !paused)
        {
            float h = sPanel.CalcHeight(new GUIContent(thoughtBody), W * 0.6f - 40) + 46;
            var r = new Rect(W * 0.2f, H - 210 - h, W * 0.6f, h);
            Panel(r, 0.72f);
            GUI.Label(new Rect(r.x + 20, r.y + 8, r.width - 40, 24), thoughtHead, sHead);
            GUI.Label(new Rect(r.x + 20, r.y + 34, r.width - 40, h - 40), thoughtBody, sPanel);
        }

        // subtitles
        if (Time.time < subUntil && !string.IsNullOrEmpty(sub) && !paused && string.IsNullOrEmpty(dlgText))
        {
            // narration and Mrs. Kapoor's lines speak through the same phrase subtitles as the conversations
            int cut = sub.IndexOf(":  ");
            string who = cut > 0 ? sub.Substring(0, cut) : null, what = cut > 0 ? sub.Substring(cut + 3) : sub;
            AudioSource src = voice != null && voice.isPlaying ? voice : (kamala != null && kamala.IsTalking ? kamala.VoiceSource : null);
            narration.Speak(W, H, who, what, src);
            if (subSkippable)
                GUI.Label(new Rect(W * 0.5f - 165f, H - 30f, 330, 20), "Space: skip line   |   Enter: skip all", new GUIStyle(sSmall) { fontSize = 13, alignment = TextAnchor.UpperCenter });
        }

        // dialogue
        if (!string.IsNullOrEmpty(dlgText) && !paused) DrawDialogue(W, H);
        if (!paused) compass.Afterglow(W, H);
        if (phase == Phase.Intro && !paused && fade < 0.9f)
            UiKit.Text(new Rect(0, H - 44, W, 26), "Enter: skip intro", new GUIStyle(sSmall) { alignment = TextAnchor.UpperCenter, fontSize = 15 });

        // fade to/from black
        if (fade > 0.001f)
        {
            var old = GUI.color; GUI.color = new Color(0, 0, 0, Mathf.Clamp01(fade));
            GUI.DrawTexture(new Rect(0, 0, W, H), Texture2D.whiteTexture);
            GUI.color = old;
        }

        // title card
        if (Time.time < titleEnd && !string.IsNullOrEmpty(titleA))
        {
            float a = Mathf.Clamp01(Mathf.Min((Time.time - titleStart) / 1.2f, (titleEnd - Time.time) / 1.2f));
            var old = GUI.color; GUI.color = new Color(1, 1, 1, a);
            GUI.Label(new Rect(0, H * 0.38f, W, 70), titleA, sTitle);
            GUI.Label(new Rect(0, H * 0.38f + 76, W, 36), titleB, sTitle2);
            GUI.color = old;
        }

        if (showEndPrompt)
        {
            Shadowed(new Rect(0, H * 0.36f, W, 70), "END OF DEMO", sTitle);
            Shadowed(new Rect(0, H * 0.36f + 76, W, 36), "Thanks for playing Act I.   Press R to play again", sTitle2);
        }

        if (journalOpen && !paused && phase != Phase.Ending) DrawJournal(W, H);
        if (phase == Phase.Title) DrawStartMenu(W, H);
        if (paused) DrawPause(W, H);

        GUI.matrix = savedMatrix;
    }

    // --- title -----------------------------------------------------------------
    void DrawStartMenu(float W, float H)
    {
        var old = GUI.color; GUI.color = Color.black;
        GUI.DrawTexture(new Rect(0, 0, W, H), Texture2D.whiteTexture);
        GUI.color = old;
        menu.Draw(W, H);
    }

    // ---------------------------------------------------- menu actions + saving
    void OnMenuPlay(int act, bool resume)
    {
        menu.Dispose();
        if (titleAmbience != null) StopCoroutine(titleAmbience);
        sfx.PlayOneShot(clickClip, 0.6f);
        if (act == 1)
        {
            if (resume && SaveSystem.Act1InProgress) ResumeActOne();
            else { SaveSystem.ResetAct(1); PlayPrologue(); }
        }
        else if (act == 2) StartActII(resume);
        else
        {
            if (!resume) SaveSystem.ResetAct(act);
            ActLoader.Load(act, builder, player, resume);      // Acts III-V
            enabled = false;
        }
    }

    /// <summary>
    /// A new game opens in the Curator's Gallery (his welcome, with the book). The flat is left standing while he
    /// talks; when he blows his candle out, the game comes back here and Act I begins.
    /// </summary>
    void PlayPrologue()
    {
        if (ambience != null) ambience.volume = 0f;           // the title-screen bed would play under him; Intro brings it back
        enabled = false;                                      // no Act I UI over the cutscene
        CuratorInterlude.Play(0, builder, player, () =>
        {
            enabled = true;
            StartCoroutine(Intro());
        }, true);
    }

    /// <summary>Back into the apartment with the clues already found marked, Mrs. Kapoor's talk remembered.</summary>
    void ResumeActOne()
    {
        var d = SaveSystem.Data;
        foundCount = 0;
        foreach (var t in builder.ClueTags)
            if (d.clues.Contains(t.id) && !t.id.StartsWith("Hook")) { t.found = true; foundCount++; }
        dlgDone = d.dlgDone; moveOnOffered = d.moveOnOffered; moveOnDeclined = d.moveOnDeclined;
        if (dlgDone && kamala != null) { Destroy(kamala.gameObject); kamala = null; }

        phase = Phase.Explore;
        skipAll = false;
        fade = 0f; fadeTarget = 0f; titleEnd = 0f;
        bellEnabled = true; nextBell = Time.time + 5f;
        StartCoroutine(RampAmbience(ambience.volume, 0.9f, 2f));
        var cc = player.GetComponent<CharacterController>();
        cc.enabled = false;
        player.transform.position = builder.transform.TransformPoint(new Vector3(-0.9f, 0.1f, -0.9f));
        cc.enabled = true;
        player.SetLook(15f, 5f);
        Cursor.lockState = CursorLockMode.Locked; Cursor.visible = false;
        PriyaRoomPlayer.Locked = false;
        startPos = player.transform.position;
        lastProgressTime = Time.time;
        Toast("Welcome back, " + SaveSystem.Profile.playerName + ".   Progress restored: " + foundCount + " of 9 clues.", 6f);
    }

    void DrawTitleScreen(float W, float H)
    {
        var old = GUI.color; GUI.color = Color.black;
        GUI.DrawTexture(new Rect(0, 0, W, H), Texture2D.whiteTexture);
        GUI.color = old;

        GUI.Label(new Rect(0, H * 0.14f, W, 70), "SHADOWS OF CHANDNI", sTitle);
        GUI.Label(new Rect(0, H * 0.14f + 72, W, 32), "A non-violent mystery thriller", sTitle2);

        var r = new Rect(W / 2 - 330, H * 0.36f, 660, 300);
        Panel(r, 0.35f);
        GUI.Label(new Rect(r.x + 24, r.y + 14, r.width - 48, 26), "HOW TO PLAY", sHead);
        string ctrl =
            "You are Arjun Mehra, a private detective. Priya Kapoor has vanished.\n" +
            "Search her apartment and find all 9 clues.\n\n" +
            "W A S D  -  walk           Mouse  -  look around           Shift  -  walk faster\n" +
            "TAB  -  detective vision: clues glow gold and get labels\n" +
            "E  -  examine the object you are looking at\n" +
            "J  -  case journal (shows every clue and where to look)\n" +
            "Esc  -  pause          Space  -  skip a voice line";
        GUI.Label(new Rect(r.x + 24, r.y + 46, r.width - 48, r.height - 56), ctrl, sPanel);

        float a = 0.6f + 0.4f * Mathf.Sin(Time.realtimeSinceStartup * 3f);
        GUI.color = new Color(1, 1, 1, a);
        GUI.Label(new Rect(0, H * 0.36f + 320, W, 36), "Press ENTER or click to begin", sPrompt);
        GUI.color = Color.white;
        GUI.Label(new Rect(0, H - 50, W, 28), "Headphones recommended  -  voiced dialogue with subtitles", new GUIStyle(sTitle2) { fontSize = 15 });
    }

    // --- pause -----------------------------------------------------------------
    void DrawPause(float W, float H)
    {
        Panel(new Rect(0, 0, W, H), 0.7f);
        GUI.Label(new Rect(0, H * 0.2f, W, 60), UiKit.Track("Paused"), sTitle);
        if (GUI.Button(new Rect(W / 2 - 130, H * 0.36f, 260, 46), "Resume", sBtn)) SetPaused(false);
        if (GUI.Button(new Rect(W / 2 - 130, H * 0.36f + 58, 260, 46), "Quit to main menu", sBtn))
        {
            SetPaused(false);
            builder.Build();
            return;
        }
        var r = new Rect(W / 2 - 330, H * 0.36f + 128, 660, 210);
        Panel(r, 0.4f);
        GUI.Label(new Rect(r.x + 20, r.y + 10, r.width - 40, 170),
            "W A S D walk  |  Mouse look  |  Shift walk faster\nTAB detective vision  |  E examine  |  J journal\nSpace skip line  |  Enter skip conversation  |  Esc resume\nF2 graphics quality (Cinematic / Balanced / Performance)", sPanel);
    }

    // --- tutorial ---------------------------------------------------------------
    void DrawTutorial(float W, float H)
    {
        bool moved = (player.transform.position - startPos).sqrMagnitude > 4f;
        bool vision = builder.VisionUsed;
        bool examined = foundCount > 0;
        bool all = moved && vision && examined;
        if (all && tutorialDoneAt < 0) tutorialDoneAt = Time.time;
        if (tutorialDoneAt > 0 && Time.time - tutorialDoneAt > 3f) return;

        var r = new Rect(W / 2 - 250, H - 190, 500, 112);
        Panel(r, 0.6f);
        GUI.Label(new Rect(r.x + 16, r.y + 8, r.width - 32, 22), all ? "Nice work, detective." : "GETTING STARTED", sHead);
        GUI.Label(new Rect(r.x + 16, r.y + 32, r.width - 32, 80),
            Check(moved) + "Walk into the room  (W A S D + mouse)\n" +
            Check(vision) + "Press TAB - clues glow gold\n" +
            Check(examined) + "Look at a glowing object and press E", sPanel);
    }

    // --- markers ----------------------------------------------------------------
    void DrawMarkers(float s, float H)
    {
        var lblStyle = new GUIStyle(sSmall) { alignment = TextAnchor.UpperCenter, fontSize = 15 };
        foreach (var t in builder.ClueTags)
        {
            if (t == null || t.found || !t.gameObject.activeInHierarchy) continue;
            bool hook = t.id.StartsWith("Hook");
            if (hook && phase != Phase.NoteReady) continue;
            Vector3 sp = camComp.WorldToScreenPoint(Center(t) + Vector3.up * 0.12f);
            if (sp.z <= 0.2f) continue;
            float x = sp.x / s, y = (Screen.height - sp.y) / s;
            ClueInfo ci; Info.TryGetValue(t.id, out ci);
            float dist = sp.z;
            var m = GUI.matrix;
            GUIUtility.RotateAroundPivot(45f, new Vector2(x, y));
            var old = GUI.color; GUI.color = new Color(1f, 0.8f, 0.2f, 0.95f);
            GUI.DrawTexture(new Rect(x - 6, y - 6, 12, 12), Texture2D.whiteTexture);
            GUI.color = old;
            GUI.matrix = m;
            Shadowed(new Rect(x - 100, y - 34, 200, 22), (ci != null ? ci.name : "?") + "  " + dist.ToString("0.0") + " m", lblStyle);
        }
    }

    // --- journal ----------------------------------------------------------------
    void DrawJournal(float W, float H)
    {
        var notes = new System.Collections.Generic.List<UiKit.Note>();
        foreach (var id in ClueOrder)
        {
            var ci = Info[id];
            bool found = false;
            foreach (var t in builder.ClueTags) if (t != null && t.id == id) found = t.found;
            notes.Add(new UiKit.Note(ci.name, found ? ci.desc : "Where to look: " + ci.where, found ? 1 : 0));
        }
        UiKit.CaseFile(W, H, "Priya Kapoor  -  Missing", "Clues found  " + foundCount + " / 9\nAll nine are needed", notes, "");
    }

    // --- dialogue ---------------------------------------------------------------
    void DrawDialogue(float W, float H)
    {
        if (dlgOptions != null) compass.Draw(W, H, dlgSpeaker);
        else compass.Speak(W, H, dlgSpeaker, dlgText, voice != null && voice.isPlaying ? voice : (kamala != null ? kamala.VoiceSource : null));
    }
}
